// backend/common/config/memory.go
package config

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"fmt"
)

// defaultsJSON is the schema's defaults, generated by internal/defaultsgen, for a build without the CUE validator.
//
//go:embed defaults.json
var defaultsJSON []byte

func decodeDefaults() (Config, error) {
	var c Config
	if err := json.Unmarshal(defaultsJSON, &c); err != nil {
		return Config{}, fmt.Errorf("config defaults: %w", err)
	}
	return c, nil
}

// decodeSeed overlays stored JSON on the defaults; empty input is the defaults, rejected input is the defaults plus the error.
func decodeSeed(raw []byte) (Config, error) {
	c, err := decodeDefaults()
	if err != nil || len(bytes.TrimSpace(raw)) == 0 {
		return c, err
	}
	if err := json.Unmarshal(raw, &c); err != nil {
		fresh, derr := decodeDefaults()
		if derr != nil {
			return Config{}, derr
		}
		return fresh, fmt.Errorf("stored config rejected: %w", err)
	}
	return c, nil
}

// patchConfig deep-merges patch into c through JSON, the shape every writer patches with.
func patchConfig(c Config, patch any) (Config, error) {
	base, err := objectOf(c)
	if err != nil {
		return Config{}, err
	}
	changes, err := objectOf(patch)
	if err != nil {
		return Config{}, fmt.Errorf("config patch: %w", err)
	}
	mergeObjects(base, changes)
	data, err := json.Marshal(base)
	if err != nil {
		return Config{}, err
	}
	var next Config
	if err := json.Unmarshal(data, &next); err != nil {
		return Config{}, fmt.Errorf("patched config: %w", err)
	}
	return next, nil
}

func objectOf(v any) (map[string]any, error) {
	data, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	var m map[string]any
	return m, json.Unmarshal(data, &m)
}

// mergeObjects copies src into dst, descending into objects present on both sides; a nil value deletes the key.
func mergeObjects(dst, src map[string]any) {
	for k, v := range src {
		if v == nil {
			delete(dst, k)
			continue
		}
		next, srcObj := v.(map[string]any)
		cur, dstObj := dst[k].(map[string]any)
		if srcObj && dstObj {
			mergeObjects(cur, next)
			continue
		}
		dst[k] = v
	}
}
